const rows = $input.all().map(i => i.json || {});
const target = rows.find(r => r.approval_status === 'approved' && r.render_status === 'queued') || rows[0];
if (!target || !target.video_key) return [];
const TOKEN = $env.HF_TOKEN || '';
const IMG_PROVIDER = $env.HF_IMAGE_PROVIDER || 'fal-ai';
const IMG_MODEL = $env.HF_IMAGE_MODEL || 'fal-ai/flux/schnell';
const VID_PROVIDER = $env.HF_VIDEO_PROVIDER || 'fal-ai';
const VID_MODEL = $env.HF_VIDEO_MODEL || 'fal-ai/wan/v2.2-5b/text-to-video';
let scenes = [];
try { scenes = JSON.parse(target.scenes_json || '[]'); } catch (e) { scenes = []; }
function findUrl(obj, depth = 0) {
  if (!obj || depth > 5) return '';
  if (typeof obj === 'string') return /^https:\/\//.test(obj) && /\.(mp4|png|jpe?g|webp)(\?|$)/i.test(obj) ? obj : '';
  if (Array.isArray(obj)) { for (const v of obj) { const u = findUrl(v, depth + 1); if (u) return u; } return ''; }
  if (typeof obj === 'object') { for (const k of ['video', 'images', 'image', 'url', 'output', 'video_url', 'image_url']) { if (obj[k] !== undefined) { const u = findUrl(obj[k], depth + 1); if (u) return u; } } }
  return '';
}
const enrichedScenes = [];
for (const s of scenes) {
  let imageUrl = s.generated_image_url || '';
  let clipUrl = s.generated_clip_url || '';
  if (TOKEN && !imageUrl) {
    try {
      const resp = await this.helpers.httpRequest({ method: 'POST', url: 'https://router.huggingface.co/' + IMG_PROVIDER + '/' + IMG_MODEL, headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt: s.image_prompt, image_size: { width: 768, height: 1344 }, num_images: 1 }), timeout: 35000 });
      imageUrl = findUrl(resp);
    } catch (e) {}
  }
  if (TOKEN && Number(s.scene_no) === 1 && !clipUrl) {
    try {
      const vResp = await this.helpers.httpRequest({ method: 'POST', url: 'https://router.huggingface.co/' + VID_PROVIDER + '/' + VID_MODEL, headers: { Authorization: 'Bearer ' + TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify({ prompt: s.motion_prompt || s.image_prompt, aspect_ratio: '9:16', num_frames: 81 }), timeout: 180000 });
      clipUrl = findUrl(vResp);
    } catch (e) {}
  }
  enrichedScenes.push({ ...s, generated_image_url: imageUrl || 'https://images.unsplash.com/photo-1585338107529-13afc5f02586?w=1080', generated_clip_url: clipUrl || '' });
}
return [{ json: { ...target, scenes_json: JSON.stringify(enrichedScenes), render_status: 'ready_for_ffmpeg' } }];
